using Godot;
using System;
using System.Linq;
public partial class MigrationScene {
 void ShowFieldSite(int i){var d=ExpeditionContentSite.All[i];var s=Field(i);var b=Panel(d.Name.ToUpperInvariant());Text(b,d.Lore);Text(b,$"ZONE TIER {d.Tier} / "+(FieldCleared(i)?"AREA CLEARED":"INFECTED NEAR THE SUPPLIES")+"\n"+(s.Outcome??""));void Act(string title,string op){Button(b,title,()=>{CloseMenu();if(!CoopRequest("content",op+":"+i))ContentAction(op+":"+i);});}
  if(d.Mode=="generator"&&!s.Repaired){Text(b,s.PowerLeft>0?$"GENERATOR / {s.PowerLeft:0} active seconds remaining. Stay in the area; its noise attracts infected.":"Restore the cold cabinet: two fuel, sixty active seconds nearby, and a noisy generator. Clear the guards before collecting the supplies.");if(s.PowerLeft<=0)Act("RUN THE GENERATOR / 2 FUEL / LOUD","power");}
  if(d.Mode=="repair"&&!s.Repaired)Act("REPAIR THE STATION / 6 "+(d.Tier==1?"TIMBER":"ALLOY"),"repair");
  if(d.Mode=="night"&&!game.Night)Text(b,"The receiver unlocks after dark. Night-only infected guard what is inside.");
  if(!s.Recovered&&!s.Stripped&&!s.Delivered){if(d.Town>=0){Text(b,"This sealed case is addressed to "+ResidentNames[d.Town][d.Giver]+" at "+ExpeditionGame.SettlementNames[d.Town]+". Keeping its contents makes their field request impossible to complete.");Act("KEEP THE CASE SEALED / RESERVE FOR THE COMMUNITY","recover");Act("BREAK THE SEAL / PERSONAL LOOT, LOST REQUEST, REPUTATION -8","strip");}else Act("SEARCH THE SUPPLIES","strip");}
  if(JourneyEnabled&&HasFieldLocker(i)){Text(b,"SEPARATE FROM THE ADDRESSED COMMUNITY CASE. SPECIALIST SHUTTER / "+LockerContents(i)+(s.LockerOpened?" / EMPTY":""));if(!s.LockerOpened&&s.SearchRemaining<=0){Act("OPEN CAREFULLY / 20 SECONDS / STAY NEARBY","locker-quiet");Act("FORCE SHUTTER / 3 SECONDS / VERY LOUD","locker-force");}}
  if(d.Mode=="rest")Act("LIGHT A SMALL FIRE / 4 TIMBER / RECOVER ENERGY","rest");Text(b,"Read more places to complete The Names We Keep in F7 > Field guide. Resolved caches stay empty in this world.");Button(b,"LEAVE",CloseMenu);
 }
 void ShowFieldGuide(){var b=Panel("THE NAMES WE KEEP / SOUTH BANK FIELD GUIDE");Button(b,"PLAN AN EXPEDITION / F5",ShowJourneyPlanner);int read=game.World.Changes.FieldSites.Count(s=>s.Read);Text(b,$"{read}/{ExpeditionContentSite.All.Length} records read / milestones at 6, 14 and 28. Locations are discovered nearby or pinned by an accepted field job. Completed loot and choices persist.");Button(b,"CLAIM EXPLORATION MILESTONES",()=>{if(!CoopRequest("content","atlas:claim"))ContentAction("atlas:claim");ShowFieldGuide();});var sc=new ScrollContainer{CustomMinimumSize=new(880,380)};b.AddChild(sc);var rows=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};sc.AddChild(rows);foreach(var t in game.World.Changes.Settlements.Where(t=>t.Index<3&&t.Visits>0)){int town=t.Index;Button(rows,"FIELD REQUESTS / "+ExpeditionGame.SettlementNames[town],()=>ShowFieldJobs(town));}for(int i=0;i<ExpeditionContentSite.All.Length;i++){int index=i;var s=Field(i);if(!s.Seen&&!s.Accepted)continue;var d=ExpeditionContentSite.All[i];var p=ExpeditionContentSite.Place(game.World,i);Button(rows,$"{d.Name} / T{d.Tier} / {(s.Delivered?"DELIVERED":s.Recovered?"CASE RESERVED":s.Stripped?"LOOT TAKEN":s.Read?"READ":"DISCOVERED")} / {p.X:0}, {p.Z:0}",()=>{var page=Panel(d.Name);Text(page,d.Lore+"\n\n"+s.Outcome);Button(page,"BACK",ShowFieldGuide);});}Text(b,game.Notice);Button(b,"BACK",()=>ShowCommunity());}
 void ShowFieldJobs(int town,int giver=-1){var b=Panel(ExpeditionGame.SettlementNames[town].ToUpperInvariant()+" / FIELD REQUESTS");Text(b,"Supply runs have no hidden deadline. Read the request, visit the marked site, keep its specialist case sealed, then return here. Stripping it is permanent. The requester must still be alive. These jobs maintain supplies and relationships; they cannot undo a failed main story.");var sc=new ScrollContainer{CustomMinimumSize=new(880,400)};b.AddChild(sc);var rows=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};sc.AddChild(rows);for(int i=0;i<ExpeditionContentSite.All.Length;i++){int index=i;var d=ExpeditionContentSite.All[i];if(d.Town!=town||giver>=0&&d.Giver!=giver)continue;var s=Field(i);Text(rows,d.Name.ToUpperInvariant()+" / "+ResidentNames[town][d.Giver]+"\n"+d.Request+"\n"+(s.Delivered?"DELIVERED / community restocked":s.Stripped?"LOST / case stripped":(Town(town).DeadResidents&(1<<d.Giver))!=0?"THE REQUESTER IS GONE":s.Recovered?"CASE READY TO RETURN":s.Accepted?"ACCEPTED / marked on M":"AVAILABLE"));void Act(string title,string op){Button(rows,title,()=>{if(!CoopRequest("content",$"job:{index}:{op}"))ContentAction($"job:{index}:{op}");ShowFieldJobs(town,giver);});}if(!s.Accepted&&!s.Stripped&&!s.Delivered)Act("ACCEPT AND MARK LOCATION","accept");if(s.Accepted&&s.Recovered&&!s.Delivered)Act("HAND OVER THE SEALED CASE","return");}Text(b,game.Notice);Button(b,"BACK",ShowFieldGuide);}
 Label contentEventHud;
 void DrawContentHud(){if(!ContentEnabled)return;if(contentEventHud==null){contentEventHud=HudLabel(12);contentEventHud.Size=new(330,100);contentEventHud.AutowrapMode=TextServer.AutowrapMode.WordSmart;}contentEventHud.Position=new(34,177);contentEventHud.Text=dungeon==null&&FieldEvent.Stage==1?$"{FieldEventName().ToUpperInvariant()} / {FieldEvent.Remaining:0}s\nM / signal marked nearby. Approach with care.":"";}
}
internal partial class ExpeditionMapCanvas {
 void DrawContentMap(){if(World.Changes?.FieldSites!=null)foreach(var s in World.Changes.FieldSites.Where(s=>s.Seen||s.Accepted)){if(s.Index<0||s.Index>=ExpeditionContentSite.All.Length)continue;var at=ExpeditionContentSite.Place(World,s.Index);var p=Map(at.X,at.Z);var color=s.Delivered||s.Stripped?Colors.Gray:s.Accepted?Colors.Gold:Colors.LightSkyBlue;DrawCircle(p,3,color);if(s.Accepted&&!s.Delivered&&!s.Stripped)DrawString(ThemeDB.FallbackFont,p+new Vector2(5,-5),ExpeditionContentSite.All[s.Index].Name,HorizontalAlignment.Left,-1,10,color);}var e=World.Changes?.FieldEvent;if(e?.Stage==1){var p=Map(e.X,e.Z);DrawCircle(p,6,Colors.OrangeRed);DrawString(ThemeDB.FallbackFont,p+new Vector2(6,12),e.Kind==0?"MIGRATING HORDE":e.Kind==1?"TRAVELLING TRADER":"COURIER IN DISTRESS",HorizontalAlignment.Left,-1,10,Colors.OrangeRed);}}
}
